import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

hinge_loss_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void hinge_loss_kernel(const float* pred, const float* targ, float* sum, int size) {
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;

    float val = 0.0f;
    if (idx < size) {
        float product = pred[idx] * targ[idx];
        val = fmaxf(0.0f, 1.0f - product);
    }
    sdata[tid] = val;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(sum, sdata[0]);
    }
}

torch::Tensor hinge_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    TORCH_CHECK(predictions.numel() == targets.numel(), 
              "Input sizes must match");
    auto predictions_contig = predictions.contiguous();
    auto targets_contig = targets.contiguous();
    int size = predictions_contig.numel();
    auto sum = torch::zeros(1, predictions_contig.options());

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    size_t shared_mem_size = block_size * sizeof(float);

    hinge_loss_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        predictions_contig.data_ptr<float>(),
        targets_contig.data_ptr<float>(),
        sum.data_ptr<float>(),
        size
    );

    return sum / size;
}
"""

hinge_loss_cpp_source = "torch::Tensor hinge_loss_cuda(torch::Tensor predictions, torch::Tensor targets);"

hinge_loss_ext = load_inline(
    name='hinge_loss_ext',
    cpp_sources=hinge_loss_cpp_source,
    cuda_sources=hinge_loss_source,
    functions=['hinge_loss_cuda'],
    verbose=True,
    extra_cflags=['-O2'],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.hinge_loss = hinge_loss_ext

    def forward(self, predictions, targets):
        return self.hinge_loss.hinge_loss_cuda(predictions, targets)
